// Applies pending SQL migrations from ./drizzle (generated by `npm run db:generate`).
//
// Used instead of `drizzle-kit migrate`, which exits silently without an error message when it
// can't talk to the Sumopod pooler. This goes through lib/db/client.ts -- the same pool/TLS setup
// the app uses -- prints which database it touches, and always reports failures with exit code 1.
// It records applied migrations in drizzle.__drizzle_migrations, the same table drizzle-kit uses.
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { closeDb, getDb, getPool } from "../lib/db/client";

const MIGRATIONS_TABLE = "drizzle.__drizzle_migrations";

async function appliedCount(): Promise<number> {
  const { rows } = await getPool().query<{ exists: boolean }>(
    "select to_regclass($1) is not null as exists",
    [MIGRATIONS_TABLE],
  );
  if (!rows[0].exists) return 0;
  const result = await getPool().query<{ count: string }>(
    `select count(*) from ${MIGRATIONS_TABLE}`,
  );
  return Number(result.rows[0].count);
}

async function main() {
  const db = getDb();
  const { rows } = await getPool().query<{ db: string }>("select current_database() as db");
  const before = await appliedCount();
  console.log(`Database "${rows[0].db}": ${before} migration(s) already applied.`);

  await migrate(db, { migrationsFolder: "./drizzle" });

  const after = await appliedCount();
  console.log(
    after > before
      ? `✓ Applied ${after - before} migration(s). Total: ${after}.`
      : `✓ Nothing to apply. Total: ${after}.`,
  );
}

main()
  .catch((error) => {
    console.error("✗ Migration failed:", error);
    process.exitCode = 1;
  })
  .finally(() => closeDb());
